  stageKey?: string;
  stageLabel?: string;
  stageSource?: "derived" | "manual";
  /** 本次成稿引用的背调留档 */
  researchId?: string;
  researchScore?: number;
  /** 正文补写状态：pending 表示正在补背调/重写，发送端会等它（有超时兜底） */
